pub(crate) fn check_claim_held(held: Option<&ClaimHeld>) -> String {
    let given = match held { Some(__nikaia_value) => __nikaia_value, None => return "refused: a claim about data from outside the program".to_owned() };
    match given {
        ClaimHeld::Proved => "proved".to_owned(),
        ClaimHeld::ProvedThrough(how) => how.to_owned(),
        ClaimHeld::Precondition(f, n) => {
            let n = *n;
            if f == "main" { "precondition of `main`, checked where the words arrive".to_owned() } else if n == 0 { format!("precondition of `{}`: proved at every call the compiler sees; any other reaches the entry that checks it", f) } else if n == 1 { format!("precondition of `{}`: one call checks it when it runs; any other call proves it or reaches the entry that checks it", f) } else { format!("precondition of `{}`: {} calls check it when they run; any other call proves it or reaches the entry that checks it", f, n) }
        },
        ClaimHeld::AtRunTime(why) => format!("checked at run time: {}", why),
        ClaimHeld::ByTheTest => "checked when the test runs".to_owned(),
        ClaimHeld::Refused => "refused: a claim about data from outside the program".to_owned(),
    }
}

pub(crate) fn check_claim_refused(held: Option<&ClaimHeld>) -> Option<String> {
    let given = match held { Some(__nikaia_value) => __nikaia_value, None => return None };
    match given {
        ClaimHeld::AtRunTime(why) => return Some(format!("refused, not proved: {}", why)),
        ClaimHeld::Precondition(f, n) => {
            let n = *n;
            if f == "main" || n == 0 { return None; }
            if n == 1 { return Some(format!("refused, precondition of `{}`: one call does not prove it", f)); }
            return Some(format!("refused, precondition of `{}`: {} calls do not prove it", f, n));
        },
        _ => return None,
    }
}

pub fn check_claims_report(claims: &collections::BTreeMap<(i64, i64), FactClaim>, source: &str, path: &str, published: &collections::BTreeMap<String, Published>, colour: bool, refuses: bool) -> String {
    let mut refused: Vec<String> = vec![];
    let mut at_run_time: Vec<String> = vec![];
    let mut arrives: Vec<String> = vec![];
    let mut by_the_test: Vec<String> = vec![];
    let mut proved: Vec<String> = vec![];
    let mut through_loops = 0;
    let mut preconditions: Vec<String> = vec![];
    let mut assumed: Vec<String> = vec![];
    let mut mains: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut line = 1;
    let mut at: i64 = 0;
    for (key, claim) in claims.iter() {
        let mut start = key.0;
        if start > source.len() as i64 { start = source.len() as i64; }
        if start > at {
            for c in nikaia_std::index::get(&source.as_bytes(), nikaia_std::index::at(at..start)).iter() {
                let c = nikaia_std::num::value(c);
                if c == b'\x0a' { line = line + 1; }
            }
            at = start;
        }
        if claim.assumed {
            assumed.push(format!("  {}:{}  {}  assumed: a fact the program vouches for in `unsafe`, checked only where the build removes no checks", path, line, claim.written));
            continue;
        }
        let how = match refuses {
            true => nikaia_std::index::or(check_claim_refused((claim.held).as_ref()), || check_claim_held((claim.held).as_ref()).into()),
            false => check_claim_held((claim.held).as_ref()),
        };
        let row = format!("  {}:{}  {}  {}", path, line, claim.written, how);
        if how == "proved" { proved.push(row); } else if how.starts_with("proved through") {
            through_loops += 1;
            proved.push(row);
        } else if how.starts_with("precondition of `main`") {
            mains.insert(claim.written.to_owned());
            arrives.push(row);
        } else if how.starts_with("precondition") && how.contains("proved at every call") { preconditions.push(row); } else if how.starts_with("precondition") || how.starts_with("checked at run time") { at_run_time.push(row); } else if how.starts_with("checked when") { by_the_test.push(row); } else if claim.held.is_some() { refused.push(row); }
    }
    let main = *nikaia_std::index::get(&published, "main");
    if main.is_some() {
        let entry = nikaia_std::index::or(match main {
            Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
            None => None,
        }, || Published::nothing());
        for k in 0..entry.requires.len() as i64 {
            if ((k) as usize) >= entry.from.len() { continue; }
            let from = nikaia_std::index::get(&entry.from, (k) as usize);
            if mains.contains(from) { continue; }
            arrives.push(format!("  {}  {}  precondition of `main` carried back from `{}`, checked where the words arrive", path, *nikaia_std::index::get(&entry.requires, (k) as usize), from));
        }
    }
    let unproved = refused.len() as i64 + at_run_time.len() as i64 + by_the_test.len() as i64;
    let done = proved.len() as i64 + preconditions.len() as i64;
    let mut looped: String = String::from("");
    if through_loops > 0 { looped = format!(", through a loop {}", through_loops); }
    let mut vouched: String = String::from("");
    if !assumed.is_empty() { vouched = format!("; assumed {}", assumed.len() as i64); }
    let mut out: String = format!("asserts in {}: {} - not proved {} (refused {}, checked at run time {}, checked by a test {}); checked where the words arrive {}; proved {} (proved {}{}, preconditions proved at every call {}){}\n", path, unproved + arrives.len() as i64 + done, unproved, refused.len() as i64, at_run_time.len() as i64, by_the_test.len() as i64, arrives.len() as i64, done, proved.len() as i64, looped, preconditions.len() as i64, vouched);
    let mut red: Vec<String> = vec![];
    red.extend(refused);
    red.extend(at_run_time);
    red.extend(by_the_test);
    let mut green: Vec<String> = vec![];
    green.extend(proved);
    green.extend(preconditions);
    out.push_str(&check_report_rows(&red, "\x1b[31m", colour));
    out.push_str(&check_report_rows(&arrives, "\x1b[94m", colour));
    out.push_str(&check_report_rows(&assumed, "\x1b[33m", colour));
    out.push_str(&check_report_rows(&green, "\x1b[32m", colour));
    out
}

pub(crate) fn check_report_rows(rows: &[String], paint: &str, colour: bool) -> String {
    let mut out: String = String::from("");
    for row in rows.iter() {
        if colour {
            out.push_str(paint);
            out.push_str(row);
            out.push_str("\x1b[0m\n");
        } else {
            out.push_str(row);
            out.push_str("\n");
        }
    }
    out
}

